std::vector<Adhesion::Node> nodes;
for (auto vit = rt.finite_vertices_begin(); vit != rt.finite_vertices_end(); ++vit) {
    Adhesion::Node node;
    Point const& p = vit->point();
    node.position = {p[0], p[1], p[2]};
    // Mass is the weight of the weighted point
    node.mass = vit->point().weight();
    // Velocity is not directly available from vertex, so set to zero or handle appropriately
    node.velocity = {0.0, 0.0, 0.0};
    // Node type classification based on edge count
    int edge_count = this->edge_count(vit, threshold);
    node.node_type = type_from_edge_count(edge_count);
    nodes.push_back(node);
}
return nodes;

